import React, { useState } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import { experience, education } from '../data/content';
import Reveal, { EASE } from './Reveal';
import SectionHead from './SectionHead';
import { Plus } from './Icons';

function Item({ item, index, open, onToggle }) {
  const id = `exp-panel-${index}`;
  return (
    <Reveal as="li" className={`exp__item ${open ? 'is-open' : ''}`} delay={0.05 * index} y={20}>
      <button className="exp__row" onClick={onToggle} aria-expanded={open} aria-controls={id}>
        <span className="exp__index mono">{String(index + 1).padStart(2, '0')}</span>
        <span>
          <span className="exp__company">{item.company}</span>
          <span className="exp__role" style={{ display: 'block' }}>
            {item.role}
          </span>
        </span>
        <span className="exp__period mono">
          {item.period}
          <small>{item.location}</small>
        </span>
        <span className="exp__chevron">
          <Plus />
        </span>
      </button>
      <AnimatePresence initial={false}>
        {open && (
          <motion.div
            id={id}
            className="exp__body"
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: 'auto', opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.55, ease: EASE }}
          >
            <div className="exp__body-inner">
              <ul className="exp__bullets">
                {item.bullets.map((b) => (
                  <li key={b}>{b}</li>
                ))}
              </ul>
              <div className="exp__tags">
                {item.tags.map((t) => (
                  <span className="tag" key={t}>
                    {t}
                  </span>
                ))}
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </Reveal>
  );
}

export default function Experience() {
  const [open, setOpen] = useState(0);

  return (
    <section id="experience" className="section">
      <div className="container">
        <SectionHead index="02" label="Experience" title="Where I've worked." />

        <div className="exp">
          <div className="exp__aside">
            <Reveal>
              <p className="mono">Six roles since 2023</p>
              <p>
                From debugging a hiring app as a high-schooler to generating SQL at scale for a bank. Every role added
                a layer, and each one taught me to ship things people rely on.
              </p>
            </Reveal>
            <Reveal className="edu" delay={0.1}>
              <span className="mono">Education · {education.period}</span>
              <div className="edu__school">{education.school}</div>
              <div className="edu__program">{education.program}</div>
              <div className="edu__courses">
                {education.courses.map((c) => (
                  <span className="tag" key={c}>
                    {c}
                  </span>
                ))}
              </div>
            </Reveal>
          </div>

          <ul className="exp__list">
            {experience.map((item, i) => (
              <Item key={item.company} item={item} index={i} open={open === i} onToggle={() => setOpen(open === i ? -1 : i)} />
            ))}
          </ul>
        </div>
      </div>
    </section>
  );
}
