import React, { useState } from 'react';
import { site } from '../data/content';
import Reveal from './Reveal';
import Magnetic from './Magnetic';
import { ArrowUpRight, Github, Linkedin } from './Icons';

export default function Contact() {
  const [copied, setCopied] = useState(false);

  const copy = async (e) => {
    if (!navigator.clipboard) return;
    e.preventDefault();
    try {
      await navigator.clipboard.writeText(site.email);
      setCopied(true);
      setTimeout(() => setCopied(false), 1800);
    } catch {
      window.location.href = `mailto:${site.email}`;
    }
  };

  return (
    <section id="contact" className="section contact">
      <div className="contact__orb" aria-hidden="true" />
      <div className="container contact__inner">
        <Reveal as="p" className="section__label mono">
          <span>05 / Contact</span>
        </Reveal>
        <Reveal as="h2" className="contact__title" delay={0.08}>
          Let's build <span className="serif">something.</span>
        </Reveal>
        <Reveal as="p" className="contact__lede" delay={0.16}>
          I'm looking for a Summer 2026 internship in software or data engineering. If you have a role, a project, or
          just a question, my inbox is open.
        </Reveal>
        <Reveal delay={0.22}>
          <a href={`mailto:${site.email}`} className="contact__email" onClick={copy} title="Click to copy">
            {site.email}
            <span className="contact__copy">{copied ? 'Copied' : 'Copy'}</span>
          </a>
        </Reveal>
        <Reveal className="contact__links" delay={0.3}>
          <Magnetic>
            <a href={site.github} className="btn btn--ghost" target="_blank" rel="noopener noreferrer">
              <Github style={{ width: 16, height: 16 }} /> GitHub <ArrowUpRight />
            </a>
          </Magnetic>
          <Magnetic>
            <a href={site.linkedin} className="btn btn--ghost" target="_blank" rel="noopener noreferrer">
              <Linkedin style={{ width: 16, height: 16 }} /> LinkedIn <ArrowUpRight />
            </a>
          </Magnetic>
          <Magnetic>
            <a href={site.resume} className="btn btn--primary" target="_blank" rel="noopener noreferrer">
              Resume <ArrowUpRight />
            </a>
          </Magnetic>
        </Reveal>
      </div>
    </section>
  );
}
