import React, { useRef } from 'react';
import { motion, useMotionValue, useSpring, useTransform, useReducedMotion } from 'framer-motion';
import { about, site } from '../data/content';
import Reveal from './Reveal';
import SectionHead from './SectionHead';
import Counter from './Counter';

function TiltPhoto() {
  const ref = useRef(null);
  const reduce = useReducedMotion();
  const mx = useMotionValue(0.5);
  const my = useMotionValue(0.5);
  const rx = useSpring(useTransform(my, [0, 1], [8, -8]), { stiffness: 120, damping: 18 });
  const ry = useSpring(useTransform(mx, [0, 1], [-8, 8]), { stiffness: 120, damping: 18 });

  const onMove = (e) => {
    if (reduce || !ref.current) return;
    const r = ref.current.getBoundingClientRect();
    mx.set((e.clientX - r.left) / r.width);
    my.set((e.clientY - r.top) / r.height);
  };
  const onLeave = () => {
    mx.set(0.5);
    my.set(0.5);
  };

  return (
    <div className="about__photo-wrap" ref={ref} onMouseMove={onMove} onMouseLeave={onLeave}>
      <div className="about__photo-frame" />
      <motion.div className="about__photo" style={{ rotateX: rx, rotateY: ry }}>
        <img src={site.profile} alt={site.name} loading="lazy" />
        <div className="about__photo-caption mono">
          <span>{site.name}</span>
          <span>{site.location}</span>
        </div>
      </motion.div>
      <div className="about__badge" aria-hidden="true">
        <svg viewBox="0 0 100 100">
          <defs>
            <path id="circle" d="M50,50 m-36,0 a36,36 0 1,1 72,0 a36,36 0 1,1 -72,0" />
          </defs>
          <text>
            <textPath href="#circle" textLength="224" lengthAdjust="spacingAndGlyphs">Open to work · Summer 2026 ·</textPath>
          </text>
        </svg>
      </div>
    </div>
  );
}

export default function About() {
  return (
    <section id="about" className="section">
      <div className="container">
        <SectionHead index="01" label="About" title="Curious builder, careful engineer." />

        <div className="about__grid">
          <Reveal>
            <TiltPhoto />
          </Reveal>

          <div className="about__text">
            {about.paragraphs.map((p, i) => (
              <Reveal as="p" key={i} delay={0.1 * i}>
                {p}
              </Reveal>
            ))}

            <dl className="about__facts">
              {about.facts.map((f, i) => (
                <Reveal as="div" className="about__fact" key={f.label} delay={0.05 * i}>
                  <dt className="mono">{f.label}</dt>
                  <dd>{f.value}</dd>
                </Reveal>
              ))}
            </dl>
          </div>
        </div>

        <div className="about__stats">
          {about.stats.map((s, i) => (
            <Reveal className="stat" key={s.label} delay={0.08 * i}>
              <div className="stat__value">
                <Counter value={s.value} suffix={s.suffix} />
              </div>
              <div className="stat__label">{s.label}</div>
            </Reveal>
          ))}
        </div>
      </div>
    </section>
  );
}
