import React from 'react';
import Reveal from './Reveal';

export default function SectionHead({ index, label, title, intro }) {
  return (
    <div className="section__head">
      <Reveal as="p" className="section__label mono">
        <span>
          {index} / {label}
        </span>
      </Reveal>
      <Reveal as="h2" className="section__title" delay={0.08}>
        {title}
      </Reveal>
      {intro && (
        <Reveal as="p" className="section__intro" delay={0.16}>
          {intro}
        </Reveal>
      )}
    </div>
  );
}
