import React from 'react';
import { motion } from 'framer-motion';
import { skills } from '../data/content';
import Reveal, { EASE } from './Reveal';
import SectionHead from './SectionHead';

function Group({ group, index }) {
  const onMove = (e) => {
    const r = e.currentTarget.getBoundingClientRect();
    e.currentTarget.style.setProperty('--mx', `${e.clientX - r.left}px`);
    e.currentTarget.style.setProperty('--my', `${e.clientY - r.top}px`);
  };

  return (
    <Reveal className="skills__group" delay={0.08 * index} onMouseMove={onMove}>
      <div className="skills__group-head">
        <h3 className="skills__group-title">{group.group}</h3>
        <span className="mono">{String(group.items.length).padStart(2, '0')}</span>
      </div>
      <motion.ul
        className="chips"
        initial="hidden"
        whileInView="show"
        viewport={{ once: true, margin: '-10% 0px' }}
        variants={{ show: { transition: { staggerChildren: 0.04, delayChildren: 0.15 + 0.08 * index } } }}
      >
        {group.items.map((item) => (
          <motion.li
            key={item}
            className="chip"
            variants={{
              hidden: { opacity: 0, y: 10, scale: 0.96 },
              show: { opacity: 1, y: 0, scale: 1, transition: { duration: 0.5, ease: EASE } },
            }}
            whileHover={{ y: -3 }}
          >
            {item}
          </motion.li>
        ))}
      </motion.ul>
    </Reveal>
  );
}

export default function Skills() {
  return (
    <section id="skills" className="section">
      <div className="container">
        <SectionHead
          index="04"
          label="Toolbox"
          title="What I work with."
          intro="Languages, frameworks, and tools I reach for. The list keeps growing."
        />
        <div className="skills__grid">
          {skills.map((g, i) => (
            <Group key={g.group} group={g} index={i} />
          ))}
        </div>
      </div>
    </section>
  );
}
