import React, { useRef } from 'react';
import { motion, useScroll, useTransform, useReducedMotion } from 'framer-motion';
import { hero, site } from '../data/content';
import { EASE } from './Reveal';
import Magnetic from './Magnetic';
import { ArrowUpRight, Download, Github, Linkedin, Mail } from './Icons';

const words = hero.headline.flatMap((part) =>
  part.text.split(' ').map((w) => ({ text: w, accent: !!part.accent }))
);

export default function Hero() {
  const ref = useRef(null);
  const reduce = useReducedMotion();
  const { scrollYProgress } = useScroll({ target: ref, offset: ['start start', 'end start'] });
  const y = useTransform(scrollYProgress, [0, 1], [0, reduce ? 0 : 140]);
  const opacity = useTransform(scrollYProgress, [0, 0.7], [1, 0]);

  const onMove = (e) => {
    const el = ref.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    el.style.setProperty('--mx', `${e.clientX - rect.left}px`);
    el.style.setProperty('--my', `${e.clientY - rect.top}px`);
  };

  return (
    <section id="top" className="hero" ref={ref} onMouseMove={onMove}>
      <div className="hero__grid" aria-hidden="true" />
      <motion.div
        className="hero__orb"
        aria-hidden="true"
        animate={reduce ? undefined : { x: [0, -60, 30, 0], y: [0, 40, -30, 0] }}
        transition={{ duration: 24, repeat: Infinity, ease: 'easeInOut' }}
      />
      <div className="hero__spotlight" aria-hidden="true" />

      <motion.div className="container hero__inner" style={{ y, opacity }}>
        <motion.p
          className="hero__eyebrow mono"
          initial={{ opacity: 0, y: 12 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8, ease: EASE, delay: 0.3 }}
        >
          <span className="dot" />
          {site.availability}
        </motion.p>

        <h1 className="hero__title">
          {words.map((w, i) => (
            <React.Fragment key={i}>
              <span className="hero__word">
                <motion.span
                  className={`hero__word-inner ${w.accent ? 'serif' : ''}`}
                  initial={reduce ? false : { y: '110%', rotate: 3 }}
                  animate={{ y: 0, rotate: 0 }}
                  transition={{ duration: 1, ease: EASE, delay: 0.45 + i * 0.05 }}
                >
                  {w.text}
                </motion.span>
              </span>{' '}
            </React.Fragment>
          ))}
        </h1>

        <div className="hero__bottom">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.9, ease: EASE, delay: 1 }}
          >
            <p className="hero__lede">{hero.lede}</p>
            <div className="hero__actions">
              <Magnetic>
                <a href="#work" className="btn btn--primary">
                  See my work <ArrowUpRight />
                </a>
              </Magnetic>
              <Magnetic>
                <a href={site.resume} target="_blank" rel="noopener noreferrer" className="btn btn--ghost">
                  Resume <Download />
                </a>
              </Magnetic>
            </div>
          </motion.div>

          <motion.div
            className="hero__side"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.9, ease: EASE, delay: 1.15 }}
          >
            <div className="hero__socials">
              <a className="hero__social" href={site.github} target="_blank" rel="noopener noreferrer" aria-label="GitHub">
                <Github />
              </a>
              <a className="hero__social" href={site.linkedin} target="_blank" rel="noopener noreferrer" aria-label="LinkedIn">
                <Linkedin />
              </a>
              <a className="hero__social" href={`mailto:${site.email}`} aria-label="Email">
                <Mail />
              </a>
            </div>
            <div className="hero__scroll mono">
              <span className="hero__scroll-line" />
              <span>Scroll</span>
            </div>
          </motion.div>
        </div>
      </motion.div>
    </section>
  );
}
